  color: #333;
  transition: all 0.3s;
}

.todo-text.completed {
  text-decoration: line-through;
  color: #999;
  opacity: 0.6;
}

.delete-button {
  padding: 6px 12px;
  background: #ff4757;
  color: white;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  font-size: 14px;
  transition: all 0.2s;
}

.delete-button:hover {
  background: #ff3838;
  transform: scale(1.05);
}

.stats {
  margin-top: 20px;
  padding-top: 20px;
  border-top: 2px solid #e0e0e0;
  text-align: center;
  color: #666;
  font-size: 14px;
}

.empty-state {
  text-align: center;
  padding: 40px 20px;
  color: #999;
  font-size: 18px;
}

.empty-state::before {
  content: "📝";
  display: block;
  font-size: 48px;
  margin-bottom: 10px;
}

